int subarraySum(List<int> nums, int k) {
  final seen = <int, int>{0: 1};
  var running = 0, count = 0;
  for (final x in nums) {
    running += x;
    count += seen[running - k] ?? 0;
    seen[running] = (seen[running] ?? 0) + 1;
  }
  return count;
}

