int longestZero(List<int> nums) {
  final first = <int, int>{0: -1};
  var run = 0, best = 0;
  for (var i = 0; i < nums.length; i++) {
    run += nums[i];
    final f = first[run];
    if (f != null) {
      if (i - f > best) best = i - f;
    } else {
      first[run] = i;
    }
  }
  return best;
}

void main() {
  print(longestZero([1, 2, -3, 3]));
}
```

