List<int> productExceptSelf(List<int> nums) {
  final out = List<int>.filled(nums.length, 1);
  var left = 1;
  for (var i = 0; i < nums.length; i++) {
    out[i] = left;
    left *= nums[i];
  }
  var right = 1;
  for (var i = nums.length - 1; i >= 0; i--) {
    out[i] *= right;
    right *= nums[i];
  }
  return out;
}

void main() {
  print(productExceptSelf([2, 3, 4]));
}
```

