int pivotIndex(List<int> nums) {
  final total = nums.fold(0, (a, b) => a + b);
  var left = 0;
  for (var i = 0; i < nums.length; i++) {
    if (left == total - left - nums[i]) return i;
    left += nums[i];
  }
  return -1;
}

void main() {
  print(pivotIndex([2, 1, -1]));
  print(pivotIndex([1, 2, 3]));
}
```

