class NumArray {
  final List<int> _p;
  NumArray(List<int> nums) : _p = List.filled(nums.length + 1, 0) {
    for (var i = 0; i < nums.length; i++) {
      _p[i + 1] = _p[i] + nums[i];
    }
  }
  int sumRange(int a, int b) => _p[b + 1] - _p[a];
}

void main() {
  final arr = NumArray([-2, 0, 3, -5, 2, -1]);
  print(arr.sumRange(0, 2));
  print(arr.sumRange(2, 5));
}
